import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key generated by Postgres (gen_random_uuid, built in since PG13). */
export const uuidPk = () => uuid("id").defaultRandom().primaryKey();

/** createdAt / updatedAt (timestamptz). updatedAt is refreshed by Drizzle on every update. */
export const timestamps = () => ({
  createdAt: timestamp("created_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

/** SQL helper for "exactly one of these columns is not null" CHECK constraints. */
export const exactlyOneNotNull = (...columns: string[]) =>
  sql.raw(`num_nonnulls(${columns.join(", ")}) = 1`);
